  for (const o of raw.tasks || []) {
    const p = props(o);
    if (!isDemoName(p.hs_task_subject)) { skipped.tasks++; continue; }
    tasks.push({ id: String(o.id), status: p.hs_task_status || '', dueAt: ts(p.hs_timestamp) });
  }
